PTX_SOURCE = r'''
.version 8.5
.target sm_80
.address_size 64

.visible .entry cross_entropy_kernel(
    .param .u64 predictions,
    .param .u64 targets,
    .param .u64 loss,
    .param .u32 batch_size,
    .param .u32 num_classes
)
{
    // registers
    .reg .u32 %tid, %bid, %blockDim, %idx;
    .reg .u64 %pred_ptr, %tgt_ptr, %loss_ptr, %offset;
    .reg .u32 %batch_sz, %num_cls, %j, %c;
    .reg .f32 %max_val, %val_f32, %temp_f32, %sum_exp, %log_sum_exp, %logit_tgt, %loss_i;
    .reg .f32 %inv_ln2, %ln2;

    // thread index
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %blockDim, %ntid.x;
    mad.lo.u32 %idx, %bid, %blockDim, %tid;

    // load kernel parameters
    ld.param.u64 %pred_ptr, [predictions];
    ld.param.u64 %tgt_ptr,  [targets];
    ld.param.u64 %loss_ptr, [loss];
    ld.param.u32 %batch_sz, [batch_size];
    ld.param.u32 %num_cls,  [num_classes];

    // out‑of‑range guard
    setp.ge.u32 %p1, %idx, %batch_sz;
    @%p1 bra DONE;

    // ---- predictions row pointer (half = 2 bytes) ----
    cvt.u64.u32 %offset, %idx;
    mul.lo.u64 %offset, %offset, %num_cls;   // idx * num_classes
    mul.lo.u64 %offset, %offset, 2;          // * sizeof(half)
    add.u64 %pred_ptr, %pred_ptr, %offset;

    // ---- load target class (int64) ----
    mul.wide.u32 %offset, %idx, 8;           // int64 stride
    add.u64 %tgt_ptr, %tgt_ptr, %offset;
    ld.global.u64 %offset, [%tgt_ptr];
    cvt.u32.u64 %c, %offset;                 // class index (assume fits in 32‑bit)

    // ---- find max logit (for numerical stability) ----
    mov.f32 %max_val, -1e20;
    mov.u32 %j, 0;
MAX_LOOP:
    setp.ge.u32 %p2, %j, %num_cls;
    @%p2 bra MAX_DONE;
    mul.wide.u32 %offset, %j, 2;
    add.u64 %offset, %pred_ptr, %offset;
    ld.global.nc.f16 %temp_f32, [%offset];
    cvt.rn.f32.f16 %val_f32, %temp_f32;
    setp.gt.f32 %p3, %val_f32, %max_val;
    @%p3 mov.f32 %max_val, %val_f32;
    add.u32 %j, %j, 1;
    bra MAX_LOOP;
MAX_DONE:

    // constants: 1/ln(2) and ln(2)
    mov.f32 %inv_ln2, 0f3fb8aa3b; // ≈ 1.44269504
    mov.f32 %ln2,    0f3f317218; // ≈ 0.69314718

    // ---- compute sum(exp(logit - max)) ----
    mov.f32 %sum_exp, 0f00000000;
    mov.u32 %j, 0;
SUM_LOOP:
    setp.ge.u32 %p4, %j, %num_cls;
    @%p4 bra SUM_DONE;
    mul.wide.u32 %offset, %j, 2;
    add.u64 %offset, %pred_ptr, %offset;
    ld.global.nc.f16 %temp_f32, [%offset];
    cvt.rn.f32.f16 %val_f32, %temp_f32;
    sub.f32 %val_f32, %val_f32, %max_val;          // logit - max
    mul.f32 %temp_f32, %val_f32, %inv_ln2;        // (logit-max)/ln2
    ex2.approx.f32 %temp_f32, %temp_f32;          // 2^{…} ≈ exp(logit-max)
    add.f32 %sum_exp, %sum_exp, %temp_f32;
    add.u32 %j, %j, 1;
    bra SUM_LOOP;
SUM_DONE:

    // ---- log_sum_exp = max + ln(sum_exp) ----
    lg2.approx.f32 %temp_f32, %sum_exp;           // log2(sum)
    mul.f32 %temp_f32, %temp_f32, %ln2;           // ln(sum)
    add.f32 %log_sum_exp, %max_val, %temp_f32;    // max + ln(sum)

    // ---- load logit of the correct class ----
    mul.wide.u32 %offset, %c, 2;
    add.u64 %offset, %pred_ptr, %offset;
    ld.global.nc.f16 %temp_f32, [%offset];
    cvt.rn.f32.f16 %logit_tgt, %temp_f32;

    // ---- per‑sample loss = -logit_tgt + log_sum_exp ----
    sub.f32 %loss_i, %log_sum_exp, %logit_tgt;

    // ---- convert to mean (divide by batch size) ----
    cvt.rn.f32.u32 %temp_f32, %batch_sz;
    div.f32 %loss_i, %loss_i, %temp_f32;

    // ---- atomic add into global loss (float32) ----
    atom.global.add.f32 [%loss_ptr], %loss_i;

DONE:
