        super().__init__()
        self.module = ptx_load(PTX_SOURCE)          # provided by the harness
        self.kernel_name = "cross_entropy_kernel"
        self.block = (256, 1, 1)                     # one thread per sample

    def forward(self, predictions, targets):
        """
        predictions : (B, C)  fp16 tensor on CUDA
        targets     : (B,)    int64 tensor on CUDA
        returns scalar fp16 tensor (mean cross‑entropy loss)
        """
        B, C = predictions.shape
        loss = torch.empty((), dtype=torch.float16, device=predictions.device)

        grid_x = (B + self.block[0] - 1) // self.block[0]
        grid = (grid_x, 1, 1)

        args = [
            predictions.data_ptr(),   # predictions pointer
            targets.data_ptr(),       # targets pointer
            loss.data_ptr(),          # output pointer
            B,                        # batch size
            C                         # num_classes
        ]

        ptx_launch(self.module, self.kernel_name, grid, self.block, args)
        return loss
